// Bush.cpp
void Bush::checkAlive(Level *level, int x, int y, int z)
{
    if (!canSurvive(level, x, y, z))
	{
        this->spawnResources(level, x, y, z, level->getData(x, y, z), 0);
        level->setTile(x, y, z, 0);
    }
}

